{"content": """"Extract a genuine agent-session transcript (JSONL) for the make.fun entry.

Reads the stored messages of the current session from state.db, keeps the segment that
built the entry, redacts known secret values, and writes a JSONL file with one record per
message: {"role", "content", "tool_calls"} — the same shape an agent session has.
"""
import json
import os
import sqlite3

DB = os.path.expanduser("~/.hermes/state.db")
OUT = "/home/node/money/entry-tagline/transcripts.jsonl"

conn = sqlite3.connect(DB)
cur = conn.cursor()
sid = cur.execute("select session_id from messages order by id desc limit 1").fetchone()[0]

rows = cur.execute(
    "select id, role, content, tool_calls, tool_name from messages where session_id = ? order by id",
    (sid,),
).fetchall()

# keep the segment that built the entry: from the first message mentioning the entry
start = next(
    (i for i, r in enumerate(rows) if r[2] and ("entry-tagline" in str(r[2]) or "makefun-tagline" in str(r[2]))),
    0,
)
segment = rows[start:]

# redact values that must not leave the machine
redactions = []
for line in open("/home/node/.makefun/credentials"):
    if '"key"' in line:
        redactions.append(json.loads("{" + line.strip().rstrip(",") + "}")["key"])
redactions += ["NcLab2026!", "NcUser2026!", "nclab2026"]


def clean(text):
    if not isinstance(text, str):
        return text
    for value in redactions:
        if value:
            text = text.replace(value, "[REDACTED:credential]")
    return text


records = []
for _id, role, content, tool_calls, tool_name in segment:
    rec = {"role": role, "content": clean(content or "")}
    if tool_calls:
        try:
            rec["tool_calls"] = json.loads(tool_calls)
        except Exception:
            rec["tool_calls"] = clean(str(tool_calls))[:4000]
    if tool_name:
        rec["tool_name"] = tool_name
    records.append(rec)

with open(OUT, "w", encoding="utf-8") as fh:
    for rec in records:
        fh.write(json.dumps(rec, ensure_ascii=False) + "\n")

print(json.dumps({"session": sid, "messages_total": len(rows), "kept": len(records), "out": OUT, "bytes": os.path.getsize(OUT)}))
", "path": "/home/node/money/makefun/make_transcript.py"}
